import { Parser, ReplacementRules, popKeys } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, createPrompt, PromptInfo, Model } from '../data';
import { ParserError } from '../exceptions';
import { loadJson } from '../utils/json';

const SAMPLER_PARAMS = ['Sampler', 'CFG scale', 'Seed', 'Steps', 'ENSD', 'Schedule type'];

const REPLACEMENT_RULES: ReplacementRules = [['Schedule type', 'scheduler']];

/**
 * Parser for images generated by AUTOMATIC1111's stable-diffusion-webui or similar
 */
export class AUTOMATIC1111Parser extends Parser {
  public readonly generator = Generators.AUTOMATIC1111;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    // CivitAI writes the parameters to the EXIF UserComment of its PNG files
    const parameterString = parameters?.parameters ?? parameters?.UserComment;
    if (typeof parameterString !== 'string') {
      throw new ParserError('error reading parameter string');
    }
    const lines = parameterString.split('\n');

    const { infoIndex, samplerInfo, metadata } = getSamplerInfo(lines);
    // SD.Next repeats the prompts as templates before the settings
    let promptLines = lines.slice(0, infoIndex);
    const templateIndex = promptLines.findIndex(line => /^(?:Negative )?[Tt]emplate:/.test(line));
    if (templateIndex > 0) {
      const templates = promptLines.slice(templateIndex).join('\n').split(/^Negative template:/m);
      metadata.Template = templates[0].replace(/^Template:\s*/, '').trim();
      if (templates[1] !== undefined) metadata['Negative template'] = templates[1].trim();
      promptLines = promptLines.slice(0, templateIndex);
    }
    const prompts = promptLines.join('\n').split('Negative prompt:');
    if (prompts.length > 2) {
      throw new ParserError('found multiple negative prompts');
    }
    const [prompt, negativePrompt] = [prompts[0], prompts[1] ?? ''].map(p => p.trim());

    // SD.Next leaves the sampler out when the default one was used
    const samplerName = samplerInfo.Sampler ?? 'unknown';
    delete samplerInfo.Sampler;

    const modelName = metadata.Model;
    const modelHash = metadata['Model hash'];
    delete metadata.Model;
    delete metadata['Model hash'];

    let model: Model | undefined;
    if (modelName || modelHash) {
      model = createModel({ name: modelName, hash: modelHash });
    }

    const sampler = createSampler(samplerName, this.normalizeParameters(samplerInfo, REPLACEMENT_RULES), {
      model,
      prompts: prompt ? [createPrompt(prompt)] : [],
      negativePrompts: negativePrompt ? [createPrompt(negativePrompt)] : [],
    });

    return createPromptInfo(this.generator, [sampler], metadata, parameters);
  }
}

/**
 * Find the line holding the sampler information, searching from the end of the parameter string
 */
function getSamplerInfo(lines: string[]): {
  infoIndex: number;
  samplerInfo: Record<string, any>;
  metadata: Record<string, any>;
} {
  for (let index = lines.length - 1; index >= 0; index--) {
    const metadata = extractMetadata(lines[index]);
    const samplerInfo = Object.fromEntries(popKeys(SAMPLER_PARAMS, metadata));
    if (Object.keys(samplerInfo).length >= 3) {
      return { infoIndex: index, samplerInfo, metadata };
    }
  }

  throw new ParserError('no sampler information found');
}

/**
 * Extract the `key: value` pairs of a parameter line.
 *
 * Values may be quoted (`Lora hashes: "a: 1, b: 2"`) or hold JSON (`Hashes: {...}`,
 * `Civitai resources: [...]`); quoted values are unquoted, JSON values decoded.
 */
export function extractMetadata(line: string): Record<string, any> {
  const metadata: Record<string, any> = {};
  let index = 0;

  while (index < line.length) {
    const keyMatch = /\s*([^,:\n]+?):\s*/y;
    keyMatch.lastIndex = index;
    const key = keyMatch.exec(line);
    if (!key) {
      // not a key: skip to the next comma
      const next = line.indexOf(',', index);
      if (next === -1) break;
      index = next + 1;
      continue;
    }

    let valueStart = keyMatch.lastIndex;
    let valueEnd: number;
    let value: any;
    const opening = line[valueStart];
    if (opening === '"' || opening === '{' || opening === '[') {
      valueEnd = findClosing(line, valueStart);
    } else {
      valueEnd = -1;
    }

    if (valueEnd !== -1) {
      const raw = line.slice(valueStart, valueEnd + 1);
      try {
        value = opening === '"' ? JSON.parse(raw) : loadJson(raw);
      } catch {
        value = opening === '"' ? raw.slice(1, -1) : raw;
      }
      index = valueEnd + 1;
      const comma = line.indexOf(',', index);
      index = comma === -1 ? line.length : comma + 1;
    } else {
      const comma = line.indexOf(',', valueStart);
      const end = comma === -1 ? line.length : comma;
      const raw = line.slice(valueStart, end).trim();
      index = end + 1;
      // a value holding `: ` belongs to an unquoted list, which can't be read reliably
      if (/:\s/.test(raw)) continue;
      value = raw;
    }

    metadata[key[1].trim()] = value;
  }

  return metadata;
}

/**
 * Find the index of the quote or bracket closing the one at `start`, or -1
 */
function findClosing(text: string, start: number): number {
  const opening = text[start];
  if (opening === '"') {
    for (let i = start + 1; i < text.length; i++) {
      if (text[i] === '\\') i++;
      else if (text[i] === '"') return i;
    }
    return -1;
  }

  const stack: string[] = [];
  let inString = false;
  for (let i = start; i < text.length; i++) {
    const char = text[i];
    if (inString) {
      if (char === '\\') i++;
      else if (char === '"') inString = false;
    } else if (char === '"') {
      inString = true;
    } else if (char === '{' || char === '[') {
      stack.push(char === '{' ? '}' : ']');
    } else if (char === '}' || char === ']') {
      if (stack.pop() !== char) return -1;
      if (stack.length === 0) return i;
    }
  }
  return -1;
}
